async function main(ctx) {
  const input = ctx.input || {};

  // Resolve room internally from runtime env.
  // Prefer ROOM_ID (threads/room context) then fallback to CONVERSATION_ID (room conversation id).
  const roomId = String(ctx.env('ROOM_ID') ?? ctx.env('CONVERSATION_ID') ?? '');

  if (!roomId) {
    throw new Error(
      "Room id not available. Ensure env('ROOM_ID') or env('CONVERSATION_ID') is set in this runtime."
    );
  }

  // Forwarded for future compatibility.
  const kinds = input.kinds ?? 'all';
  const q = typeof input.q === 'string' ? input.q : '';
  const limitPerKind = Number.isFinite(Number(input.limitPerKind)) ? Number(input.limitPerKind) : 200;
  const includeArchived = typeof input.includeArchived === 'boolean' ? input.includeArchived : true;

  return { roomId, q, kinds, limitPerKind, includeArchived };
}

function unwrap(resp) {
  if (!resp || typeof resp !== 'object') return resp;
  const body = resp.body;
  if (body && typeof body === 'object') {
    if (body.success === true && body.data !== undefined) return body.data;
    if (body.data !== undefined) return body.data;
  }
  return body ?? resp;
}

function compact(arr) {
  return (Array.isArray(arr) ? arr : []).filter(Boolean);
}

function leanPinnedItem(item, key) {
  if (!item || typeof item !== 'object') return null;
  const obj = item[key] && typeof item[key] === 'object' ? item[key] : null;

  const slug = obj && obj.slug != null ? String(obj.slug) : undefined;
  const name = obj && obj.name != null ? String(obj.name) : undefined;
  const archived = obj && typeof obj.archived === 'boolean' ? obj.archived : undefined;

  return { slug, name, archived };
}

function leanToolItem(item) {
  if (!item || typeof item !== 'object') return null;
  const tool = item.tool && typeof item.tool === 'object' ? item.tool : null;
  const assignment = item.assignment && typeof item.assignment === 'object' ? item.assignment : {};
  if (!tool) return null;
  return {
    slug: tool.slug != null ? String(tool.slug) : undefined,
    name: tool.name != null ? String(tool.name) : undefined,
    permission: assignment.permission != null ? String(assignment.permission) : undefined
  };
}

function leanUser(u) {
  if (!u || typeof u !== 'object') return null;
  const slug = u.slug != null ? String(u.slug) : undefined;
  const name = u.displayName != null ? String(u.displayName) : (slug ?? undefined);
  return { slug, name };
}

function leanAgent(a) {
  if (!a || typeof a !== 'object') return null;
  const slug = a.slug != null ? String(a.slug) : undefined;
  const name = a.name != null ? String(a.name) : (slug ?? undefined);
  return { slug, name, role: 'agent' };
}

async function main(ctx) {
  const resp = ctx.lastOutputOf('resources');
  const r = unwrap(resp) || {};

  const pins = {
    views: compact((r.views || []).map((x) => leanPinnedItem(x, 'view'))),
    tables: compact((r.tables || []).map((x) => leanPinnedItem(x, 'table'))),
    taskBoards: compact((r.taskBoards || []).map((x) => leanPinnedItem(x, 'taskBoard')))
  };

  const tools = compact((r.tools || []).map(leanToolItem));

  const participants = r.participants && typeof r.participants === 'object' ? r.participants : {};
  const users = compact((participants.users || []).map(leanUser));
  const agents = compact((participants.agents || []).map(leanAgent));

  return { pins, tools, participants: { users, agents } };
}
